import numpy as np
# Normalize each spectrum by the max intensity in the G band range (1550-1620 cm-1)
mask = (x >= 1550) & (x <= 1620)
if np.any(mask):
    g_max = np.max(y1[mask])
    if g_max > 0:
        y1 = y1 / g_max
    else:
        y1 = y1 * 0.0
else:
    # Fallback if no data in range, normalize by global max to avoid division by zero
    g_max = np.max(y1)
    if g_max > 0:
        y1 = y1 / g_max
    else:
        y1 = y1 * 0.0
